[TFMListIdAttribute('OrdersWithImage'), TFMListIdAttribute('Orders')]
class TFMListOrdersWithImage extends TFMList
{
    boolean useWideLines;
}

Method.Source:
    public TFMListConfiguration getList()
    {
        TFMListConfiguration				listConfig	= TFMListConfiguration::Construct(listName);
        TFMListRow							row			= listConfig.addRow();        
        TFMListColumn						column		= row.makeColumn(93);
        TFMListImageElement					img;
        column.addElement(TFMListTextElement::ConstructTextElement('{DisplayLine1_Label}: {DisplayLine1}',TFMFonts::FindOrCreateFromProperties('contentFontBold',TFMFontSizes::medium,true,false,'').id));

        column		= row.makeColumn(7);
        img = TFMListImageElement::ConstructImageElement('','Status',7,0);
        img.addValueElement('1','unlocked');
        img.addValueElement('2',resourceStr(TFMLocked));
        column.addElement(img);

        listConfig.parmDisplayStatus(true);
        row			= listConfig.addRow();        
        TFMList::makeColumnsInRowElement(row,2,useWideLines ? 1 : 2,82,2);
        column		= row.makeColumn(18);
        column.addElement(TFMListImageElement::ConstructImageElement('{imageId}','',18,0));        

        column.addElement(TFMListImageElement::ConstructImageElement('{attachmentImage}','',7,0,SysChartHorizontalAlignment::Right,TFMVerticalAlignment::Bottom));
        if (useWideLines)
        {
            row			= listConfig.addRow();
			TFMList::makeDisplayLinesInRowElement(row,1,100,4);
			row			= listConfig.addRow();
			TFMList::makeDisplayLinesInRowElement(row,1,100,5);
        }
        return listConfig;
    }
